"""Movie catalogue for the review stream (generated by scripts/build_library.py).

The Kaggle IMDB reviews dataset has no movie titles, so the producer assigns each
review to one of these titles. `positivity` (derived from the title's IMDb score)
is the probability that a review for that title is drawn from the positive class,
so each movie develops its own audience reaction. `buzz` is its relative share of
the stream.
"""
import json
import os

with open(os.path.join(os.path.dirname(__file__), "catalog.json")) as _f:
    MOVIES = json.load(_f)

BY_TITLE = {m["title"]: m for m in MOVIES}
YEARS = {m["title"]: m["year"] for m in MOVIES}

# Every movie in the poster archive (users can write reviews for any of them).
with open(os.path.join(os.path.dirname(__file__), "library.json")) as _f:
    LIBRARY = json.load(_f)
LIB_BY_ID = {m["id"]: m for m in LIBRARY}
LIB_BY_TITLE = {}
for _m in LIBRARY:                       # library is sorted by votes: first = most popular
    LIB_BY_TITLE.setdefault(_m["title"], _m)
